var e={machineDoctor:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Un scan en lecture seule de tout ce qui est vérifiable — conflits de broches, valeurs des drivers, dérive de config, lint du projet, sync du firmware, changements matériels, santé de l'installation — noté A-F. Chaque constat pointe vers le widget qui le corrige.`}},scanning:{t:0,b:{t:2,i:[{t:3}],s:`Scan…`}},rescan:{t:0,b:{t:2,i:[{t:3}],s:`Relancer le scan`}},scoreLine:{t:0,b:{t:2,i:[{t:3,v:`Score `},{t:4,k:`score`},{t:3,v:` / 100`}]}},counts:{t:0,b:{t:2,i:[{t:4,k:`errors`},{t:3,v:` erreur(s) · `},{t:4,k:`warnings`},{t:3,v:` avertissement(s)`}]}},scoreHint:{t:0,b:{t:2,i:[{t:3}],s:`Combinaison pondérée des piliers ci-dessous. Les contrôles de santé (Intégrité config, Sync firmware, Services) notent ce que l'on a pu mesurer : l'Intégrité config perd 25 par erreur et 8 par avertissement. Les étapes de configuration que vous n'avez pas encore lancées (Input shaping, Débit max, Drivers moteur) comptent pour zéro tant qu'elles ne sont pas faites ; les terminer fait donc monter le score. Les signaux illisibles pour l'instant ne vous pénalisent pas.`}},allClear:{t:0,b:{t:2,i:[{t:3}],s:`Rien à signaler.`}},notChecked:{t:0,b:{t:2,i:[{t:3}],s:`Impossible à vérifier (imprimante injoignable ou pas de référence).`}},assessment:{healthy:{t:0,b:{t:2,i:[{t:3}],s:`Bon état - tout ce que l'application peut vérifier semble correct et la configuration est terminée.`}},attention:{t:0,b:{t:2,i:[{t:3,v:`Globalement sain, mais `},{t:4,k:`pillar`},{t:3,v:` nécessite de l'attention.`}]}},critical:{t:0,b:{t:2,i:[{t:4,k:`pillar`},{t:3,v:` présente un problème à corriger.`}]}},setup_incomplete:{t:0,b:{t:2,i:[{t:3,v:`Rien de cassé, mais la configuration n'est pas encore terminée - `},{t:4,k:`pillars`},{t:3,v:` restant(s) à effectuer.`}]}},clean_but_findings:{t:0,b:{t:2,i:[{t:3,v:`Rien de cassé, mais il reste `},{t:4,k:`warnings`},{t:3,v:` avertissement(s) à résoudre.`}]}}},pillars:{title:{t:0,b:{t:2,i:[{t:3}],s:`Détail de santé`}},notMeasured:{t:0,b:{t:2,i:[{t:3}],s:`non mesuré`}},notDone:{t:0,b:{t:2,i:[{t:3}],s:`pas encore effectué`}}},pillar:{config:{t:0,b:{t:2,i:[{t:3}],s:`Intégrité config`}},firmware:{t:0,b:{t:2,i:[{t:3}],s:`Sync firmware`}},services:{t:0,b:{t:2,i:[{t:3}],s:`Services`}},tuning:{t:0,b:{t:2,i:[{t:3}],s:`Input shaping`}},flow:{t:0,b:{t:2,i:[{t:3}],s:`Débit max`}},drivers:{t:0,b:{t:2,i:[{t:3}],s:`Drivers moteur`}}},services:{title:{t:0,b:{t:2,i:[{t:3}],s:`Services`}},active:{t:0,b:{t:2,i:[{t:3}],s:`actif`}},inactive:{t:0,b:{t:2,i:[{t:3}],s:`arrêté`}},none:{t:0,b:{t:2,i:[{t:3}],s:`Aucun service.`}}},stats:{title:{t:0,b:{t:2,i:[{t:3}],s:`En un coup d'œil`}},maxFlow:{t:0,b:{t:2,i:[{t:3}],s:`Débit max`}},tuningAxis:{t:0,b:{t:2,i:[{t:3,v:`Shaper `},{t:4,k:`axis`}]}},firmware:{t:0,b:{t:2,i:[{t:3}],s:`Firmware`}},outOfSync:{t:0,b:{t:2,i:[{t:4,k:`n`},{t:3,v:` désynchronisé(s)`}]}},allSynced:{t:0,b:{t:2,i:[{t:3}],s:`tout synchronisé`}},none:{t:0,b:{t:2,i:[{t:3}],s:`Pas encore de mesures.`}}},category:{pins:{t:0,b:{t:2,i:[{t:3}],s:`Câblage des broches`}},drivers:{t:0,b:{t:2,i:[{t:3}],s:`Valeurs des drivers`}},drift:{t:0,b:{t:2,i:[{t:3}],s:`Dérive de config`}},project:{t:0,b:{t:2,i:[{t:3}],s:`Projet de config`}},firmware:{t:0,b:{t:2,i:[{t:3}],s:`Sync du firmware`}},hardware:{t:0,b:{t:2,i:[{t:3}],s:`Changements matériels`}},install:{t:0,b:{t:2,i:[{t:3}],s:`Santé de l'installation`}}},status:{ok:{t:0,b:{t:2,i:[{t:3}],s:`OK`}},warn:{t:0,b:{t:2,i:[{t:3}],s:`Avertissements`}},fail:{t:0,b:{t:2,i:[{t:3}],s:`Problèmes`}},unknown:{t:0,b:{t:2,i:[{t:3}],s:`Non vérifié`}},todo:{t:0,b:{t:2,i:[{t:3}],s:`Non effectué`}}},link:{config_section:{t:0,b:{t:2,i:[{t:3}],s:`Éditeur de configuration`}},config_file:{t:0,b:{t:2,i:[{t:3}],s:`Éditeur de configuration`}},stepper:{t:0,b:{t:2,i:[{t:3}],s:`Drivers moteur`}},topology_node:{t:0,b:{t:2,i:[{t:3}],s:`Topologie des cartes`}},widget:{t:0,b:{t:2,i:[{t:3}],s:`Ouvrir`}}},finding:{pins:{double_assign:{t:0,b:{t:2,i:[{t:3,v:`La broche `},{t:4,k:`pin`},{t:3,v:` de `},{t:4,k:`mcu`},{t:3,v:` est affectée dans plusieurs sections.`}]}},caveat:{t:0,b:{t:2,i:[{t:3,v:`La broche `},{t:4,k:`pin`},{t:3,v:` de `},{t:4,k:`mcu`},{t:3,v:` porte une mise en garde électronique.`}]}}},drivers:{over_driver_cap:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:` : run_current `},{t:4,k:`run_current`},{t:3,v:` A dépasse le plafond du driver ~`},{t:4,k:`cap`},{t:3,v:` A.`}]}},near_driver_cap:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:` : run_current `},{t:4,k:`run_current`},{t:3,v:` A est à moins de 10% du plafond ~`},{t:4,k:`cap`},{t:3,v:` A.`}]}},over_motor_rating:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:` : run_current `},{t:4,k:`run_current`},{t:3,v:` A dépasse la valeur nominale de `},{t:4,k:`motor`},{t:3,v:` (`},{t:4,k:`max_current`},{t:3,v:` A).`}]}},near_motor_rating:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:` : run_current `},{t:4,k:`run_current`},{t:3,v:` A est à moins de 10% de la valeur nominale de `},{t:4,k:`motor`},{t:3,v:` (`},{t:4,k:`max_current`},{t:3,v:` A).`}]}},odd_microsteps:{t:0,b:{t:2,i:[{t:4,k:`section`},{t:3,v:` : microsteps `},{t:4,k:`microsteps`},{t:3,v:` n'est pas une puissance de deux.`}]}}},drift:{pending:{t:0,b:{t:2,i:[{t:3}],s:`Klipper a des changements SAVE_CONFIG en attente.`}},param:{t:0,b:{t:2,i:[{t:3,v:`[`},{t:4,k:`section`},{t:3,v:`] `},{t:4,k:`key`},{t:3,v:` : disque `},{t:4,k:`disk`},{t:3,v:` ≠ live `},{t:4,k:`live`},{t:3,v:`.`}]}},klipper_warning:{t:0,b:{t:2,i:[{t:4,k:`text`}]}}},project:{broken_include:{t:0,b:{t:2,i:[{t:4,k:`file`},{t:3,v:` : l'include "`},{t:4,k:`message`},{t:3,v:`" ne pointe vers aucun fichier.`}]}},orphan_driver:{t:0,b:{t:2,i:[{t:4,k:`file`},{t:3,v:` : la section driver "`},{t:4,k:`message`},{t:3,v:`" n'a pas de stepper correspondant.`}]}}},firmware:{out_of_sync:{t:0,b:{t:2,i:[{t:4,k:`mcu`},{t:3,v:` : le firmware `},{t:4,k:`mcu_version`},{t:3,v:` diffère de l'hôte `},{t:4,k:`host_version`},{t:3,v:`.`}]}}},hardware:{changed:{t:0,b:{t:2,i:[{t:4,k:`mcu`},{t:3,v:` : matériel modifié (`},{t:4,k:`kind`},{t:3,v:`).`}]}},no_baseline:{t:0,b:{t:2,i:[{t:3}],s:`Pas de référence matérielle — enregistrez un instantané dans la Topologie des cartes.`}}},install:{check_failed:{t:0,b:{t:2,i:[{t:3,v:`Contrôle d'installation échoué : `},{t:4,k:`name`},{t:3,v:` — `},{t:4,k:`detail`},{t:3,v:`.`}]}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Aide`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`À propos de Machine Doctor`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Fermer`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`Comment lire`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`Appuyez sur Rescanner pour une vérification en lecture seule de toute l'imprimante.`}},{t:0,b:{t:2,i:[{t:3}],s:`Lisez la note A–F et les barres de piliers pour repérer les points faibles.`}},{t:0,b:{t:2,i:[{t:3}],s:`Ouvrez le lien d'un résultat pour aller droit au widget qui le corrige.`}}],topics:{scan:{title:{t:0,b:{t:2,i:[{t:3}],s:`Ce que couvre l'analyse`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Un passage en lecture seule sur tout ce que l'app peut vérifier — conflits de broches, valeurs des drivers, écart entre la config enregistrée et active, lint du projet, synchro du firmware, changements matériels vs la référence, et santé de l'installation. Elle n'exécute jamais rien sur l'imprimante.`}}},grade:{title:{t:0,b:{t:2,i:[{t:3}],s:`La note A–F`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Le score combine deux choses. Les contrôles de santé (Intégrité config, Sync firmware, Services) notent ce que l'on a pu mesurer. Les étapes de configuration - Input shaping, Débit max et réglage des Drivers moteur - comptent pour zéro tant que vous ne les avez pas lancées : une imprimante non réglée obtient donc un score bas même si rien n'est cassé, et chaque étape terminée fait monter le chiffre. La note en lettre découle directement de ce score, et un signal illisible pour l'instant (Moonraker ou l'hôte hors ligne) est simplement écarté au lieu de vous pénaliser.`}}},fixes:{title:{t:0,b:{t:2,i:[{t:3}],s:`Liens de saut vers la correction`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Chaque résultat porte un bouton qui renvoie directement au widget qui le résout (Éditeur de config, Moteurs, la Carte de la machine…), du problème à la solution en un clic.`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Termes utilisés ici`}}}},glossary:{grade:{term:{t:0,b:{t:2,i:[{t:3}],s:`Note (A–F)`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Une seule lettre résumant la santé de l'imprimante, dérivée des scores des piliers ; A est sain, F demande de l'attention.`}}},pillar:{term:{t:0,b:{t:2,i:[{t:3}],s:`Pilier`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Une catégorie de santé notée indépendamment — p. ex. intégrité de la config, synchro firmware, services, input shaping, débit max.`}}},finding:{term:{t:0,b:{t:2,i:[{t:3}],s:`Résultat`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Un problème précis détecté par l'analyse, avec sa gravité et un lien vers le widget qui le corrige.`}}}}},listSep:{t:0,b:{t:2,i:[{t:3}],s:`, `}},setup:{line:{t:0,b:{t:2,i:[{t:3,v:`Achèvement de la configuration : `},{t:4,k:`done`},{t:3,v:` / `},{t:4,k:`total`},{t:3,v:` étapes effectuées`}]}}},readiness:{title:{t:0,b:{t:2,i:[{t:3}],s:`Avancement de la configuration`}},banner:{t:0,b:{t:2,i:[{t:3}],s:`Configuration non terminée : les étapes non lancées comptent pour zéro et retiennent le score. Lancez-les pour le faire monter.`}},runIt:{t:0,b:{t:2,i:[{t:3}],s:`Lancer`}}}}};export{e as default};